def load(path):
    return json.load(open(path))


BASE_NAMES = {"parameter_events", "get_parameters", "get_parameter_types", "set_parameters", "set_parameters_atomically",
              "describe_parameters", "list_parameters", "clock"}


def phase_columns(d, graph_path):
    """per node: counted E by the phase of its F (data / init / zero_exec) and, for non-OK nodes,
    the counted E that no expected row's literal name explains — by phase."""
    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    import aw_a2_expected as m
    g = load(graph_path); by = {n["id"]: n for n in g["nodes"]}
    out = {}
    for n in g["nodes"]:
        if n.get("type") != "N":
            continue
        r = d["nodes"].get(n.get("full_name"))
        if not r or not r.get("expected"):
            continue
        E = []
        for c in n.get("children", []):
            e = by.get(c)
            if not e or e.get("type") != "E" or e.get("etype") == "oore":
                continue
            ph = [by[f].get("phase") for f in e.get("children", []) if by.get(f, {}).get("type") == "F" and by[f].get("split") != "response"]
            E.append((e.get("label", ""), e.get("etype"), ph[0] if ph else "noF"))
        cnt = collections.Counter(ph for _l, _t, ph in E)
        remaps = r.get("launch_remaps") or {}
        claimed = collections.Counter()
        for x in r["rows"]:
            if not x["delta"][0] or x.get("resolved") == "absent":
                continue
            nm = m.literal_name(x["code"])
            if not nm:
                continue
            key = nm[2:] if nm.startswith("~/") else nm
            tgt = remaps.get(key) or remaps.get(nm) or nm
            claimed[tgt.rstrip("/").rsplit("/", 1)[-1]] += (x.get("mult") or 1)
        un = collections.Counter(); un_names = []
        for lab, et, ph in E:
            b = lab.rsplit("/", 1)[-1]
            if b in BASE_NAMES:
                continue
            if claimed.get(b, 0) > 0:
                claimed[b] -= 1; continue
            un[ph] += 1; un_names.append(f"{b}({et},{ph})")
        out[n["full_name"]] = {"data": cnt.get("data", 0), "init": cnt.get("init", 0), "zero": cnt.get("zero_exec", 0), "noF": cnt.get("noF", 0),
                               "un_data": un.get("data", 0), "un_init": un.get("init", 0), "un_zero": un.get("zero_exec", 0),
                               "un_names": ", ".join(un_names)[:1500]}
    return out


