def expected_tab(d, ph=None):
    ph = ph or {}
    rows = [["Node full_name", "kind", "class", "class how", "exp E", "exp F", "exp pub", "exp cli", "act E", "act F", "act pub", "act waitable", "Δ E", "Δ F", "verdict", "range", "resolved (loops/created/absent)",
             "E data", "E init", "E zero_exec", "unexplained data", "unexplained init", "unexplained zero_exec", "unexplained E (name,etype,phase)", "notes"]]
    tE = tF = aE = aF = 0
    for full, r in sorted(d["nodes"].items()):
        if not r.get("expected"):
            continue
        e, ac = r["expected"], r["actual"]
        tE += e["E"]; tF += e["F"]; aE += ac["E"]; aF += ac["F"]
        res = e.get("resolved", {}); p = ph.get(full, {})
        rows.append([full, r["kind"], r.get("class") or "", r.get("class_how") or "", e["E"], e["F"], e["pub"], e["cli"],
                     ac["E"], ac["F"], ac["pub"], len(ac.get("waitable", [])), r["delta"]["E"], r["delta"]["F"], r["verdict"],
                     str(e.get("range", "")), f"{res.get('loops', 0)}/{res.get('created', 0)}/{res.get('absent', 0)}",
                     p.get("data", ""), p.get("init", ""), p.get("zero", ""),
                     "" if r["verdict"] == "OK" else p.get("un_data", ""), "" if r["verdict"] == "OK" else p.get("un_init", ""),
                     "" if r["verdict"] == "OK" else p.get("un_zero", ""), "" if r["verdict"] == "OK" else p.get("un_names", ""),
                     "; ".join(r.get("notes", []))])
    rows += [[], ["TOTAL (modelled)", "", "", "", tE, tF, "", "", aE, aF, "", "", aE - tE, aF - tF, "OK" if (aE == tE and aF == tF) else "mismatch", "", "",
                  sum(p.get("data", 0) for p in ph.values()), sum(p.get("init", 0) for p in ph.values()), sum(p.get("zero", 0) for p in ph.values()),
                  sum(p.get("un_data", 0) for f, p in ph.items() if d["nodes"][f]["verdict"] != "OK"), sum(p.get("un_init", 0) for f, p in ph.items() if d["nodes"][f]["verdict"] != "OK"),
                  sum(p.get("un_zero", 0) for f, p in ph.items() if d["nodes"][f]["verdict"] != "OK"), "", ""]]
    # verdict × phase summary block
    rows += [[], ["verdict × phase", "nodes", "E total", "E data", "E init", "E zero_exec", "unexplained data", "unexplained init", "unexplained zero_exec"]]
    for v in ["OK", "OK:range", "mismatch:ctx", "mismatch:plugins", "mismatch"]:
        fs = [f for f, r in d["nodes"].items() if r.get("expected") and r["verdict"] == v]
        P = [ph.get(f, {}) for f in fs]
        rows.append([v, len(fs), sum(p.get("data", 0) + p.get("init", 0) + p.get("zero", 0) + p.get("noF", 0) for p in P),
                     sum(p.get("data", 0) for p in P), sum(p.get("init", 0) for p in P), sum(p.get("zero", 0) for p in P),
                     "" if v == "OK" else sum(p.get("un_data", 0) for p in P), "" if v == "OK" else sum(p.get("un_init", 0) for p in P), "" if v == "OK" else sum(p.get("un_zero", 0) for p in P)])
    cli = [r for r in d["nodes"].values() if r["kind"] == "ros2cli"]
    rows += [[], [f"+ ros2cli helpers ({len(cli)})", "", "", "", "", "", "", "", sum(r["actual"]["E"] for r in cli), sum(r["actual"]["F"] for r in cli), "", "", "", "", "", "runtime/CLI noise — not in static model"]]
    return rows


def actual_tab(d):
    rows = [["Node full_name", "pid", "E", "F", "sub topics", "srv", "tmr periods (ns)", "waitables", "other E", "pub topics", "cli"]]
    for full, r in sorted(d["nodes"].items()):
        a = r["actual"]
        rows.append([full, r.get("pid"), a["E"], a["F"], ", ".join(a["sub"])[:1500], ", ".join(a["serv"])[:1500], ", ".join(a["tmr"])[:300],
                     ", ".join(a.get("waitable", []))[:500], ", ".join(a.get("other", []))[:300], ", ".join(a.get("pub_topics", []))[:1500], ", ".join(a.get("cli_names", []))[:500]])
    return rows


def reviews_tab(d):
    rows = [["Node full_name", "#", "Class (where the row was found)", "Source file", "Line", "Exact code", "VCC code", "Resulting vertex (E/F/pub/cli)", "Method", "ctx (if/for/lambda)", "Rule"]]
    for full, r in sorted(d["nodes"].items()):
        if not r.get("expected"):
            continue
        e = r["expected"]
        base = e["base"]
        rows.append([full, 0, r.get("class") or "", "(baseline)", "", "rclcpp::Node ctor" + (" + LifecycleNode" if r.get("lifecycle") else "") + (" + /clock (use_sim_time)" if e.get("clock") else ""),
                     "VCC1" + (".lc" if r.get("lifecycle") else "") + (" + VCC1.sim" if e.get("clock") else ""),
                     f"+{base[0] + (1 if e.get('clock') else 0)} E + {base[1] + (1 if e.get('clock') else 0)} F + {base[2]} pub", "", "", r.get("class_how") or ""])
        for i, row in enumerate(r["rows"], 1):
            dE, dF, dP, dC = row["delta"]
            res = " + ".join(x for x in [f"{dE} E" if dE else "", f"{dF} F" if dF else "", f"{dP} pub" if dP else "", f"{dC} cli" if dC else ""] if x) or "—"
            rows.append([full, i, row.get("cls", ""), row["file"], row["line"], row["code"], row["vcc"], "+" + res, row.get("method", ""), row.get("ctx", ""), row.get("desc", "")])
    return rows


